/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: subject, cid, stored, ordered, entry, rows, album
 * Tests
 *   - entries take the replaced positions in entry order, extra entries follow the last of them, and they lead a list that had none
 *   - other Credits keep their subject, role and relative order, and every order is renumbered by position
 *   - a kept Credit keeps its phrase only while its successor is unchanged; an entry's own phrase is stored only before the next entry
 *   - an entry showing a captured Credit keeps its Credit ID; new Credit IDs are deterministic and valid
 *   - a label replaces the first label Credit in place with its phrase, or follows the last Artist Credit; the same subject changes nothing
 *   - a member's entries replace its legacy unspecified Credits only for the Artists they name
 *   - a rebuilt list the Credit rules refuse throws for a write, while an unvalidated one only renumbers
 *   - a captured list reads as the stored list, and equality ignores nothing but key order
 * @end-catalog */

/**
 * The Credits an applied existing-Album review writes (adminCatalogReviewCredits.ts): where selected entries go among the stored
 * Credits, which join phrases stay, which Credit IDs are kept or derived, where a label goes, which legacy Credits a member's
 * entries replace, and the Credit rules a rebuilt list must still meet. Every identity and name is synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import {
    albumReplaced, capturedCatalogCredits, memberReplaced, rebuildReviewCredits, reviewCreditId, sameCredits, type ReviewEntryCredit
} from '../../src/administration/catalog/adminCatalogReviewCredits';
import { CatalogCreditValidationError, type CatalogCredit } from '../../src/models/catalogCredit';
import type { CatalogReviewCapturedCredit } from '../../src/administration/catalog/adminCatalogReviewContract';

const subject = (n: number) => n.toString(16).padStart(24, '0');
/** A valid Credit ID (8 to 100 characters) named by `name`; a `review_` ID is kept as it is. */
const cid = (name: string) => name.startsWith('review_') ? name : `credit_${name}`;
const stored = (creditId: string, subjectType: CatalogCredit['subjectType'], n: number, role: CatalogCredit['role'], joinPhrase?: string): CatalogCredit =>
    ({ creditId: cid(creditId), subjectType, subjectId: subject(n), role, order: 0, ...(joinPhrase === undefined ? {} : { joinPhrase }) });
const ordered = (credits: CatalogCredit[]) => credits.map((credit, order) => ({ ...credit, order }));
/** An entry Credit: `creditId` is the captured Credit's for an entry that shows one, else a new one. */
const entry = (creditId: string, n: number, role: 'primary' | 'featured' = 'primary', joinPhrase: string | null = null): ReviewEntryCredit =>
    ({ entry: { key: `0000000a-0000-4000-8000-${String(n).padStart(12, '0')}`, name: `Synthetic ${n}`, role, joinPhrase, musicBrainzId: null }, subjectId: subject(n), creditId: cid(creditId) });
/** The rebuilt list as `name:role[phrase]` rows. */
const rows = (credits: readonly CatalogCredit[]) => credits.map(credit => `${credit.creditId.replace(/^credit_/, '')}:${credit.role}${credit.joinPhrase === undefined ? '' : `[${credit.joinPhrase}]`}`);
const album = (credits: CatalogCredit[], entries: ReviewEntryCredit[]) => rebuildReviewCredits(ordered(credits), { entries: { credits: entries, replaced: albumReplaced } });

test('entries take the replaced positions in entry order, extra entries follow the last of them, and they lead a list that had none', () => {
    const list = [stored('a', 'artist', 1, 'primary'), stored('p', 'artist', 9, 'performer'), stored('b', 'artist', 2, 'featured'), stored('l', 'organization', 30, 'label')];
    // Reordered: B takes A's position and A takes B's; the performer stays between them.
    assert.deepEqual(rows(album(list, [entry('b', 2, 'featured'), entry('a', 1)])), ['b:featured', 'p:performer', 'a:primary', 'l:label']);
    // An extra entry follows the last replaced position, before the label.
    assert.deepEqual(rows(album(list, [entry('a', 1), entry('b', 2, 'featured'), entry('new', 3, 'featured')])), ['a:primary', 'p:performer', 'b:featured', 'new:featured', 'l:label']);
    // Fewer entries drop the positions left over.
    assert.deepEqual(rows(album(list, [entry('a', 1)])), ['a:primary', 'p:performer', 'l:label']);
    // Without a replaced Credit the entries lead the list.
    assert.deepEqual(rows(album([stored('p', 'artist', 9, 'performer'), stored('l', 'organization', 30, 'label')], [entry('x', 4), entry('y', 5)])), ['x:primary', 'y:primary', 'p:performer', 'l:label']);
    assert.deepEqual(rows(album([], [entry('x', 4)])), ['x:primary']);
});

test('other Credits keep their subject, role and relative order, and every order is renumbered by position', () => {
    const list = [stored('c', 'artist', 8, 'composer'), stored('a', 'artist', 1, 'primary'), stored('pr', 'artist', 7, 'producer'), stored('pub', 'organization', 31, 'publisher'), stored('b', 'artist', 2, 'primary')];
    const rebuilt = album(list, [entry('n', 3)]);
    assert.deepEqual(rebuilt.map(credit => [credit.creditId, credit.subjectId, credit.role, credit.order]),
        [[cid('c'), subject(8), 'composer', 0], [cid('n'), subject(3), 'primary', 1], [cid('pr'), subject(7), 'producer', 2], [cid('pub'), subject(31), 'publisher', 3]]);
});

test('a kept Credit keeps its phrase only while its successor is unchanged; an entry\'s own phrase is stored only before the next entry', () => {
    const list = [stored('a', 'artist', 1, 'primary', ' & '), stored('b', 'artist', 2, 'primary', ' feat. '), stored('p', 'artist', 9, 'performer', ' with '), stored('c', 'artist', 8, 'composer')];
    // Unchanged entries rebuild the stored list exactly, a phrase leading into another role included.
    assert.ok(sameCredits(album(list, [entry('a', 1, 'primary', ' & '), entry('b', 2)]), ordered(list)));
    // An appended entry: A keeps its phrase before B, B takes the draft's phrase before the new entry, and the performer, whose
    // successor is unchanged, keeps its own.
    assert.deepEqual(rows(album(list, [entry('a', 1, 'primary', ' & '), entry('b', 2, 'primary', ' x '), entry('n', 3, 'featured')])),
        ['a:primary[ & ]', 'b:primary[ x ]', 'n:featured', 'p:performer[ with ]', 'c:composer']);
    // A removed entry: B's phrase led into the performer, which now follows A's replacement; A's stored phrase led into B and goes.
    assert.deepEqual(rows(album(list, [entry('a', 1)])), ['a:primary', 'p:performer[ with ]', 'c:composer']);
    // A kept Credit whose successor changes loses its phrase.
    const before = [stored('c', 'artist', 8, 'composer', ' / '), stored('a', 'artist', 1, 'primary')];
    assert.deepEqual(rows(album(before, [entry('n', 3)])), ['c:composer', 'n:primary']);
    // Entries that are not adjacent never take their draft phrase.
    const split = [stored('a', 'artist', 1, 'primary'), stored('p', 'artist', 9, 'performer'), stored('b', 'artist', 2, 'primary')];
    assert.deepEqual(rows(album(split, [entry('a', 1, 'primary', ' & '), entry('b', 2)])), ['a:primary', 'p:performer', 'b:primary']);
    // A null draft phrase between adjacent entries removes the stored one.
    assert.deepEqual(rows(album(list, [entry('a', 1, 'primary', null), entry('b', 2)])), ['a:primary', 'b:primary[ feat. ]', 'p:performer[ with ]', 'c:composer']);
});

test('an entry showing a captured Credit keeps its Credit ID; new Credit IDs are deterministic and valid', () => {
    const id = reviewCreditId({ catalogReview: subject(1), operationId: '00000001-0000-4000-8000-000000000001', owner: 'album', entryKey: 'k' });
    assert.match(id, /^review_[0-9a-f]{40}$/);
    assert.equal(reviewCreditId({ catalogReview: subject(1), operationId: '00000001-0000-4000-8000-000000000001', owner: 'album', entryKey: 'k' }), id);
    assert.notEqual(reviewCreditId({ catalogReview: subject(1), operationId: '00000001-0000-4000-8000-000000000002', owner: 'album', entryKey: 'k' }), id);
    const rebuilt = album([stored('kept', 'artist', 1, 'primary')], [entry('kept', 1), entry(id, 2, 'featured')]);
    assert.deepEqual(rebuilt.map(credit => credit.creditId), [cid('kept'), id]);
});

test('a label replaces the first label Credit in place with its phrase, or follows the last Artist Credit; the same subject changes nothing', () => {
    const list = ordered([stored('a', 'artist', 1, 'primary'), stored('c', 'artist', 8, 'composer'), stored('l1', 'organization', 30, 'label', ' / '), stored('l2', 'organization', 31, 'label')]);
    const replaced = rebuildReviewCredits(list, { label: { subjectId: subject(32), creditId: 'review_label' } });
    assert.deepEqual(replaced.map(credit => [credit.creditId, credit.subjectId, credit.joinPhrase]),
        [[cid('a'), subject(1), undefined], [cid('c'), subject(8), undefined], ['review_label', subject(32), ' / '], [cid('l2'), subject(31), undefined]]);
    assert.ok(sameCredits(rebuildReviewCredits(list, { label: { subjectId: subject(30), creditId: 'review_label' } }), list));
    // Without a label Credit it goes right after the last Artist Credit, or first without one.
    const unlabeled = ordered([stored('a', 'artist', 1, 'primary', ' & '), stored('c', 'artist', 8, 'composer'), stored('pub', 'organization', 31, 'publisher')]);
    assert.deepEqual(rows(rebuildReviewCredits(unlabeled, { label: { subjectId: subject(32), creditId: 'review_label' } })), ['a:primary[ & ]', 'c:composer', 'review_label:label', 'pub:publisher']);
    assert.deepEqual(rows(rebuildReviewCredits(ordered([stored('pub', 'organization', 31, 'publisher')]), { label: { subjectId: subject(32), creditId: 'review_label' } })), ['review_label:label', 'pub:publisher']);
    // Entries go first, then the label after the last Artist Credit of the rebuilt list.
    const both = rebuildReviewCredits(ordered([stored('a', 'artist', 1, 'primary', ' & ')]), { entries: { credits: [entry('a', 1, 'primary', ' & '), entry('n', 3)], replaced: albumReplaced },
        label: { subjectId: subject(32), creditId: 'review_label' } });
    assert.deepEqual(rows(both), ['a:primary[ & ]', 'n:primary', 'review_label:label']);
});

test('a member\'s entries replace its legacy unspecified Credits only for the Artists they name', () => {
    const list = ordered([stored('l1', 'artist', 1, 'legacyUnspecified'), stored('l2', 'artist', 2, 'legacyUnspecified'), stored('c', 'artist', 3, 'composer')]);
    const rebuilt = rebuildReviewCredits(list, { entries: { credits: [entry('n', 1)], replaced: memberReplaced(new Set([subject(1)])) } });
    assert.deepEqual(rows(rebuilt), ['n:primary', 'l2:legacyUnspecified', 'c:composer']);
    assert.equal(memberReplaced(new Set())(stored('l', 'artist', 1, 'legacyUnspecified')), false);
    assert.equal(memberReplaced(new Set([subject(1)]))(stored('o', 'organization', 1, 'legacyUnspecified')), false);
    assert.equal(albumReplaced(stored('l', 'artist', 1, 'legacyUnspecified')), false);
});

test('a rebuilt list the Credit rules refuse throws for a write, while an unvalidated one only renumbers', () => {
    const many = ordered(Array.from({ length: 45 }, (_, index) => stored(`c${index}`, 'artist', 100 + index, 'composer')));
    const entries = Array.from({ length: 10 }, (_, index) => entry(`n${index}`, index + 1));
    assert.throws(() => rebuildReviewCredits(many, { entries: { credits: entries, replaced: albumReplaced } }), CatalogCreditValidationError);
    const shown = rebuildReviewCredits(many, { entries: { credits: entries, replaced: albumReplaced } }, { validate: false });
    assert.deepEqual([shown.length, shown[54].order], [55, 54]);
    // One Artist resolved for two entries of one role is refused as well.
    assert.throws(() => rebuildReviewCredits([], { entries: { credits: [entry('x', 1), { ...entry('y', 2), subjectId: subject(1) }], replaced: albumReplaced } }), CatalogCreditValidationError);
});

test('a captured list reads as the stored list, and equality ignores nothing but key order', () => {
    const captured: CatalogReviewCapturedCredit[] = [
        { creditId: cid('a'), subjectType: 'artist', subjectId: subject(1), role: 'primary', joinPhrase: ' & ', entryKey: 'k', subject: { name: 'Synthetic', musicBrainzId: null, revision: 'r' } },
        { creditId: cid('l'), subjectType: 'organization', subjectId: subject(30), role: 'label', joinPhrase: null, entryKey: null, subject: null }];
    const list = capturedCatalogCredits(captured);
    assert.deepEqual(list, [{ creditId: cid('a'), subjectType: 'artist', subjectId: subject(1), role: 'primary', order: 0, joinPhrase: ' & ' },
        { creditId: cid('l'), subjectType: 'organization', subjectId: subject(30), role: 'label', order: 1 }]);
    assert.ok(sameCredits(list, [{ order: 0, role: 'primary', subjectId: subject(1), subjectType: 'artist', creditId: cid('a'), joinPhrase: ' & ' }, list[1]]));
    assert.equal(sameCredits(list, [list[1], list[0]]), false);
    assert.equal(sameCredits(list, [{ ...list[0], joinPhrase: ' / ' }, list[1]]), false);
    assert.equal(sameCredits(list, [list[0], { ...list[1], creditId: cid('x') }]), false);
    assert.equal(sameCredits([{ ...list[0], subjectId: 'bad' }], [{ ...list[0], subjectId: 'bad' }]), false);
});
